// Audience measurement for the published gallery: writes the Umami tracker
// tag into every HTML page of a built site, after the build and before the
// deploy (.github/workflows/deploy-github-pages.yaml).
//
// The gallery's pages are generated by the sketch-gallery package and the
// sketches' pages are copied as they are, so the one place where every page
// can be reached is the built folder. Nothing here is secret: the tag ends up
// in the HTML. An empty UMAMI_WEBSITE_ID is the kill switch: no tag, nothing
// sent; a host outside UMAMI_DOMAINS (localhost, a fork) loads the tracker
// but never counts.
//
//   node scripts/inject-umami.js <dist folder>
//
//   UMAMI_WEBSITE_ID  the site's id in the Umami dashboard (default: the
//                     gallery's own); empty = no tag
//   UMAMI_SRC         the tracker's address (default: the owner's instance,
//                     named /insight: filter lists block /script.js)
//   UMAMI_DOMAINS     hosts allowed to report, comma-separated (default: the
//                     gallery's own domain and the GitHub Pages host);
//                     anything else loads but never counts
//
// Umami is self-hosted by the owner, cookie-free, and the tag asks it to
// honour Do Not Track and to drop the query and the fragment of an address.

const { readFileSync, writeFileSync } = require("node:fs");
const { htmlFiles } = require("./html-files.js");

const DEFAULT_SRC = "https://insight.steevepommier.com/insight";
const DEFAULT_WEBSITE_ID = "66bbc932-2bef-4b32-ba37-d07163f3d639";
const DEFAULT_DOMAINS = "art.steeve.website,costardrouge.github.io";
const MARKER = 'data-umami="audience"';

function escapeAttribute(value) {
  return String(value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}

function trackerTag({ src, website, domains }) {
  return (
    `<script async ${MARKER} src="${escapeAttribute(src)}" ` +
    `data-website-id="${escapeAttribute(website)}" ` +
    `data-domains="${escapeAttribute(domains)}" ` +
    'data-do-not-track="true" data-exclude-search="true" data-exclude-hash="true"></script>'
  );
}

function settings(env) {
  const website = (env.UMAMI_WEBSITE_ID === undefined ? DEFAULT_WEBSITE_ID : env.UMAMI_WEBSITE_ID).trim();
  if (!website) return null;
  let src = DEFAULT_SRC;
  try {
    const custom = new URL((env.UMAMI_SRC || "").trim() || DEFAULT_SRC);
    if (custom.protocol === "https:" || custom.protocol === "http:") src = custom.href;
  } catch {
    // an unusable address keeps the default tracker
  }
  const domains = (env.UMAMI_DOMAINS === undefined ? DEFAULT_DOMAINS : env.UMAMI_DOMAINS)
    .split(",")
    .map((d) => d.trim().toLowerCase())
    .filter(Boolean)
    .join(",");
  return { src, website, domains };
}

// Inserts the tag before </head> (the first one, any case); a page without a
// head is left alone, and a page that already carries the tag is not given a
// second one, so the script can run twice without harm.
function inject(html, tag) {
  if (html.includes(MARKER)) return null;
  const at = html.search(/<\/head\s*>/i);
  if (at < 0) return null;
  return `${html.slice(0, at)}${tag}\n${html.slice(at)}`;
}

function main() {
  const dir = process.argv[2];
  if (!dir) {
    console.error("usage: node scripts/inject-umami.js <dist folder>");
    process.exit(1);
  }
  const config = settings(process.env);
  if (!config) {
    console.log("inject-umami: UMAMI_WEBSITE_ID is empty, no page gets the tracker.");
    return;
  }
  const tag = trackerTag(config);
  let written = 0;
  let skipped = 0;
  for (const file of htmlFiles(dir)) {
    const next = inject(readFileSync(file, "utf8"), tag);
    if (next === null) skipped += 1;
    else {
      writeFileSync(file, next);
      written += 1;
    }
  }
  console.log(`inject-umami: tracker written into ${written} page(s), ${skipped} left alone.`);
}

if (require.main === module) main();

module.exports = { inject, settings, trackerTag, DEFAULT_SRC, DEFAULT_DOMAINS, MARKER };
